/* Welsh Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Rhys": "enthusiasm, ardor — Welsh", "Gwen": "white, blessed — Welsh", "Dylan": "son of the wave — Welsh dy + llanw", "Carys": "love — Welsh caru", "Owain": "The name of Owain Glyndwr, Prince of Wales.", "Branwen": "blessed raven — Welsh bran + gwen", "Price": "The fossilized patronymic: ap Rhys became Price.", "Bowen": "The fossilized patronymic: ab Owain became Bowen.", "Jones": "The most common Welsh surname.", "Llewellyn": "The name of the last native princes, now a surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Rhys';
console.log(lookup(q));

